import hashlib
import hmac
import os
import struct
import socket
import threading
from typing import Optional, Tuple

# Secure message framing protocol for inter-service communication
# Protocol: [4-byte msg_type][4-byte payload_len][payload][32-byte hmac]

SECRET_KEY = os.urandom(32)
MAX_PAYLOAD_SIZE = 65536
BUFFER_POOL_SIZE = 1048576  # 1MB shared buffer pool

class BufferPool:
    """Pre-allocated buffer pool for zero-copy message handling."""
    def __init__(self, size: int = BUFFER_POOL_SIZE):
        self._pool = bytearray(size)
        self._size = size
        self._lock = threading.Lock()
        self._write_pos = 0

    def allocate(self, nbytes: int) -> memoryview:
        """Allocate nbytes from the pool, returning a memoryview slice."""
        if nbytes <= 0:
            raise ValueError("Cannot allocate non-positive bytes")
        with self._lock:
            if self._write_pos + nbytes > self._size:
                self._write_pos = 0  # wrap around
            start = self._write_pos
            self._write_pos += nbytes
            return memoryview(self._pool)[start:start + nbytes]

    def read_at(self, offset: int, length: int) -> bytes:
        """Read length bytes from pool at given offset."""
        if offset < 0 or length < 0 or offset + length > self._size:
            raise ValueError("Invalid read bounds")
        return bytes(self._pool[offset:offset + length])


class MessageAuthenticator:
    """HMAC-based message authentication."""
    def __init__(self, key: bytes):
        if len(key) < 32:
            raise ValueError("Key must be at least 32 bytes")
        self._key = key

    def sign(self, data: bytes) -> bytes:
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def verify(self, data: bytes, signature: bytes) -> bool:
        expected = hmac.new(self._key, data, hashlib.sha256).digest()
        return hmac.compare_digest(expected, signature)


class FrameParser:
    """Parse and validate incoming message frames."""

    HEADER_SIZE = 8  # 4 bytes msg_type + 4 bytes payload_len
    HMAC_SIZE = 32

    # Message types
    MSG_DATA = 1
    MSG_CONTROL = 2
    MSG_HEARTBEAT = 3

    VALID_MSG_TYPES = {MSG_DATA, MSG_CONTROL, MSG_HEARTBEAT}

    def __init__(self, authenticator: MessageAuthenticator, pool: BufferPool):
        self._auth = authenticator
        self._pool = pool

    def parse_frame(self, raw: bytes) -> Optional[Tuple[int, bytes]]:
        """Parse a raw frame, verify integrity, return (msg_type, payload).

        Returns None if frame is invalid or authentication fails.
        Frame format: [msg_type:u32][payload_len:u32][payload][hmac:32bytes]
        """
        if len(raw) < self.HEADER_SIZE + self.HMAC_SIZE:
            return None

        # Parse header fields as UNSIGNED integers
        msg_type, payload_len = struct.unpack('<II', raw[:self.HEADER_SIZE])

        # Validate message type
        if msg_type not in self.VALID_MSG_TYPES:
            return None

        # Validate payload length against maximum
        # Security: reject oversized payloads to prevent memory exhaustion
        if payload_len > MAX_PAYLOAD_SIZE:
            return None

        # Explicit zero-length check
        if payload_len == 0:
            return None

        # Calculate expected frame size
        expected_size = self.HEADER_SIZE + payload_len + self.HMAC_SIZE
        if len(raw) < expected_size:
            return None

        # Extract components
        payload_data = raw[self.HEADER_SIZE:self.HEADER_SIZE + payload_len]
        sig_offset = self.HEADER_SIZE + payload_len
        signature = raw[sig_offset:sig_offset + self.HMAC_SIZE]

        # Verify HMAC over header + payload
        authenticated_portion = raw[:self.HEADER_SIZE + payload_len]
        if not self._auth.verify(authenticated_portion, signature):
            return None

        # Store in buffer pool for zero-copy processing
        buf = self._pool.allocate(payload_len)
        buf[:] = payload_data

        return (msg_type, bytes(payload_data))

    def validate_payload_bounds(self, payload_len: int) -> bool:
        """Additional bounds validation for payload length.

        Ensures payload_len is within acceptable range for pool allocation.
        """
        if payload_len <= 0:
            return False
        if payload_len > MAX_PAYLOAD_SIZE:
            return False
        return True


class SecureChannel:
    """Handles bidirectional secure communication."""

    def __init__(self, host: str, port: int):
        self._host = host
        self._port = port
        self._pool = BufferPool()
        self._auth = MessageAuthenticator(SECRET_KEY)
        self._parser = FrameParser(self._auth, self._pool)
        self._handlers = {
            FrameParser.MSG_DATA: self._handle_data,
            FrameParser.MSG_CONTROL: self._handle_control,
            FrameParser.MSG_HEARTBEAT: self._handle_heartbeat,
        }

    def _handle_data(self, payload: bytes) -> bytes:
        """Process data message - extract embedded records."""
        if len(payload) < 4:
            return b'ERROR'

        # First 4 bytes = record count (unsigned)
        record_count = struct.unpack('<I', payload[:4])[0]

        # Validate record count
        if record_count > 1000:
            return b'TOO_MANY_RECORDS'

        # Process each record: [2-byte len][data]
        offset = 4
        records = []
        for _ in range(record_count):
            if offset + 2 > len(payload):
                break
            rec_len = struct.unpack('<H', payload[offset:offset+2])[0]
            offset += 2
            if offset + rec_len > len(payload):
                break
            records.append(payload[offset:offset+rec_len])
            offset += rec_len

        return b'OK:' + str(len(records)).encode()

    def _handle_control(self, payload: bytes) -> bytes:
        """Process control message."""
        return b'ACK'

    def _handle_heartbeat(self, payload: bytes) -> bytes:
        """Process heartbeat."""
        return b'PONG'

    def process_incoming(self, raw_data: bytes) -> Optional[bytes]:
        """Process a raw incoming frame from the network."""
        result = self._parser.parse_frame(raw_data)
        if result is None:
            return None

        msg_type, payload = result
        handler = self._handlers.get(msg_type)
        if handler:
            return handler(payload)
        return None

    def create_frame(self, msg_type: int, payload: bytes) -> bytes:
        """Create an authenticated frame for sending."""
        if len(payload) > MAX_PAYLOAD_SIZE:
            raise ValueError("Payload too large")
        header = struct.pack('<II', msg_type, len(payload))
        authenticated = header + payload
        signature = self._auth.sign(authenticated)
        return authenticated + signature

    def serve(self):
        """Start listening for connections."""
        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        srv.bind((self._host, self._port))
        srv.listen(5)

        while True:
            conn, addr = srv.accept()
            threading.Thread(
                target=self._handle_connection,
                args=(conn,),
                daemon=True
            ).start()

    def _handle_connection(self, conn: socket.socket):
        """Handle a single client connection."""
        try:
            while True:
                # Read frame length prefix (4 bytes, unsigned)
                len_data = self._recv_exact(conn, 4)
                if not len_data:
                    break

                frame_len = struct.unpack('<I', len_data)[0]

                # Validate frame length
                if frame_len == 0 or frame_len > MAX_PAYLOAD_SIZE + FrameParser.HEADER_SIZE + FrameParser.HMAC_SIZE:
                    break

                # Read the frame
                frame_data = self._recv_exact(conn, frame_len)
                if not frame_data:
                    break

                # Process and respond
                response = self.process_incoming(frame_data)
                if response:
                    resp_frame = self.create_frame(FrameParser.MSG_DATA, response)
                    conn.sendall(struct.pack('<I', len(resp_frame)) + resp_frame)
        except (ConnectionError, struct.error):
            pass
        finally:
            conn.close()

    def _recv_exact(self, conn: socket.socket, n: int) -> Optional[bytes]:
        """Receive exactly n bytes from connection."""
        if n <= 0:
            return None
        data = b''
        while len(data) < n:
            chunk = conn.recv(n - len(data))
            if not chunk:
                return None
            data += chunk
        return data


if __name__ == '__main__':
    channel = SecureChannel('127.0.0.1', 8443)
    print("Starting secure channel on port 8443...")
    channel.serve()
